[{"col_type":"movie_3","name":"引擎","path":"ds","rule":"js:// ===== 毒舌电影(duse0) 解析引擎 =====
// 站点特性：cdndefend 反爬（静态挑战，需固定 cookie）、图片走 vres.esadj.com、播放页 m3u8 在 playSource 内联脚本
var ds = {};

// ---- 配置 ----
ds.DEFAULT_HOST = 'https://www.duse0.com';
// cdndefend 静态挑战 cookie（SHA-1 PoW：s1(c+i)[10]==0xB0 && [11]==0x0B，c 固定，故 cookie 固定）
ds.COOKIE = 'cdndefend_js_cookie=A9406FDB0F42A7C4E79E2D2EDF603F545FA32B5036572';
ds.UA = 'Mozilla/5.0 (Linux; Android 12; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/122.0.0.0 Mobile Safari/537.36';
ds.IMG_HOST = 'https://vres.esadj.com';
ds.PALETTE = ['#FF6B81', '#3AA0FF', '#FFA800', '#2CBB6E', '#9B6BFF', '#FF7F50'];
// 选中态统一用「底色 + 白字」表示（不再用引号/●○ 等符号标记）
ds.ON = { backgroundColor: '#FF6B81', textColor: '#FFFFFF' };
ds.OFF = {};

ds.host = function () {
  var h = getItem('ds_host', ds.DEFAULT_HOST) || ds.DEFAULT_HOST;
  h = String(h).replace(/\s+/g, '');
  if (!/^https?:\/\//.test(h)) h = 'https://' + h;
  return h.replace(/\/+$/, '');
};
ds.hd = function (ref) {
  return { 'User-Agent': ds.UA, 'Cookie': getItem('ds_ck', ds.COOKIE), 'Referer': ref || (ds.host() + '/') };
};

// ===== cdndefend 动态求解 =====
// 挑战：找最小 i 使 sha1(c+i) 的第 n1、n1+1 字节 == 0xB0、0x0B，其中 n1 = parseInt(c[0],16)
// cookie = 'cdndefend_js_cookie=' + c + i
ds.sha1 = function (msg) {
  function rotl(n, s) { return (n << s) | (n >>> (32 - s)); }
  var i, j;
  var msglen = msg.length;
  var words = [];
  for (i = 0; i < msglen - 3; i += 4)
    words.push(msg.charCodeAt(i) << 24 | msg.charCodeAt(i + 1) << 16 | msg.charCodeAt(i + 2) << 8 | msg.charCodeAt(i + 3));
  switch (msglen % 4) {
    case 0: words.push(0x080000000); break;
    case 1: words.push(msg.charCodeAt(msglen - 1) << 24 | 0x0800000); break;
    case 2: words.push(msg.charCodeAt(msglen - 2) << 24 | msg.charCodeAt(msglen - 1) << 16 | 0x08000); break;
    case 3: words.push(msg.charCodeAt(msglen - 3) << 24 | msg.charCodeAt(msglen - 2) << 16 | msg.charCodeAt(msglen - 1) << 8 | 0x80); break;
  }
  while (words.length % 16 != 14) words.push(0);
  words.push(msglen >>> 29);
  words.push(msglen << 3);
  var w = new Array(80);
  var h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0;
  var a, b, c, d, e, f, k, t;
  for (j = 0; j < words.length; j += 16) {
    for (i = 0; i < 16; i++) w[i] = words[j + i] | 0;
    for (i = 16; i < 80; i++) w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    a = h0; b = h1; c = h2; d = h3; e = h4;
    for (i = 0; i < 80; i++) {
      if (i < 20) { f = (b & c) | ((~b) & d); k = 0x5A827999; }
      else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
      else { f = b ^ c ^ d; k = 0xCA62C1D6; }
      t = (rotl(a, 5) + f + e + k + w[i]) | 0;
      e = d; d = c; c = rotl(b, 30); b = a; a = t;
    }
    h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0; h4 = (h4 + e) | 0;
  }
  var hex = '';
  var arr = [h0, h1, h2, h3, h4];
  for (i = 0; i < 5; i++) for (j = 7; j >= 0; j--) hex += ((arr[i] >>> (j * 4)) & 0xF).toString(16);
  return hex;
};
// 解析 fetch 返回（含 withStatusCode / 850 挑战页）
// ========== 网络：禁止对 850 页走 OkGo（Java 异常会穿透 JS try/catch）==========
ds.isChallenge = function (h) {
  h = String(h || '');
  return !h || h.indexOf('cdndefend') >= 0 || h.indexOf('verifying your browser') >= 0 || h.indexOf('Protected by') >= 0;
};
ds.guard = function (h) {
  h = String(h || '');
  return !!(h.length > 3000 && !ds.isChallenge(h) && (h.indexOf('<html') >= 0 || h.indexOf('section-box') >= 0 || h.indexOf('vod') >= 0));
};
// 仅 WebView 取页（过 cdndefend，不触发 OkGo 850 报错）
ds.hash = function (s) {
  s = String(s || '');
  var h = 0;
  for (var i = 0; i < s.length; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
  return String(h);
};
ds.readCache = function (u) {
  var k = 'ds_hc_' + ds.hash(u);
  var t = parseInt(getMyVar(k + '_t', '0'), 10) || 0;
  if (Date.now() - t > 180000) return '';
  var h = getMyVar(k, '');
  return ds.guard(h) ? h : '';
};
ds.writeCache = function (u, h) {
  if (!ds.guard(h)) return;
  var k = 'ds_hc_' + ds.hash(u);
  try {
    putMyVar(k, h);
    putMyVar(k + '_t', String(Date.now()));
  } catch (e) { log('ds cache write skip: ' + e); }
};
ds.fetchHtml = function (u, ref, noCache) {
  u = String(u || '');
  ref = ref || (ds.host() + '/');
  if (!noCache) {
    var c = ds.readCache(u);
    if (c) { log('ds cache hit len=' + c.length); return c; }
  }
  // 只走 WebView：cdndefend 挑战 cookie 绑定在同一条连接上（实测裸 fetch 必然 850），
  // 且裸 fetch 命中 850 时会抛 OkGo Java 异常，穿透 JS try/catch，
  // 导致上层 ArticleListModel 拿到 error:// 并报 “Expected URL scheme 'http'... but was 'error'”。
  for (var t = 0; t < 3; t++) {
    try {
      var h = fetchCodeByWebView(u) || '';
      if (ds.guard(h)) {
        log('ds webview ok try=' + t + ' len=' + h.length);
        ds.writeCache(u, h);
        return h;
      }
      log('ds webview weak try=' + t + ' len=' + String(h).length);
    } catch (e) {
      log('ds webview err try=' + t + ' ' + e);
    }
  }
  return '';
};
ds.getChallenge = function () { return ''; };
ds.solvePow = function (c) { return -1; };
ds.ensureCookie = function (force) { return getItem('ds_ck', '') || ''; };
ds.lastRaw = '';

ds.abs = function (u) {
  if (!u) return '';
  u = String(u);
  if (u.indexOf('http://') === 0 || u.indexOf('https://') === 0) return u;
  if (u.indexOf('//') === 0) return 'https:' + u;
  return ds.host() + (u.charAt(0) === '/' ? u : '/' + u);
};
ds.pic = function (u) {
  if (!u) return '';
  u = String(u);
  if (u.indexOf('//') === 0) u = 'https:' + u;
  else if (u.indexOf('http') !== 0) u = ds.IMG_HOST + (u.charAt(0) === '/' ? u : '/' + u);
  // 图床直连易被 OkGo 报 403/5xx，走代理减少日志报错
  if (u.indexOf('wsrv.nl') >= 0 || u.indexOf('images.weserv.nl') >= 0) return u;
  return 'https://wsrv.nl/?url=' + encodeURIComponent(u) + '&n=-1';
};
ds.clean = function (s) {
  return String(s == null ? '' : s).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&').replace(/"/g, '"').replace(/\s+/g, ' ').trim();
};
ds.baseUrl = function () {
  var v = getMyVar('ds_page_url', '');
  if (v && /^https?:\/\//.test(v)) return v;
  var u = '';
  try { u = String(MY_URL || ''); } catch (e) { }
  // 兼容旧链接
  u = u.split('@rule=')[0].split('#')[0];
  if (u.indexOf('hiker://') === 0 || !u) return getMyVar('ds_page_url', ds.host() + '/');
  return u;
};
// 禁止 https://站点@rule= ：海阔会先 OkGo 预拉页面，850 直接进不了二级
ds.detailUrl = function (href) {
  var u = ds.abs(href);
  return $('hiker://empty#immersiveTheme##noRecordHistory#').rule(function (pageUrl) {
    putMyVar('ds_page_url', pageUrl);
    $.require('ds').detail();
  }, u);
};
ds.epUrl = function (href) {
  var u = ds.abs(href);
  // lazyRule：点击时再解析，避免预加载触发 OkGo
  return $('hiker://empty#noLoading#').lazyRule(function (pageUrl) {
    putMyVar('ds_page_url', pageUrl);
    return $.require('ds').play();
  }, u);
};

// ---- 列表卡片解析（v-item）----
ds.parseCards = function (html) {
  var out = [];
  var re = /<a href="([^"]+)" class="v-item"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(html)) !== null) {
    var href = m[1], blk = m[2];
    var tm = /class="v-item-title">([^<]+)</.exec(blk);
    if (!tm) continue;
    var im = /(?:data-original|src)="([^"]*vod1[^"]*)"/.exec(blk);
    var top = /v-item-top-left">\s*<span>([^<]+)<\/span>/.exec(blk);
    var bot = /v-item-bottom">\s*<span>\s*([^<\s]+)/.exec(blk);
    var desc = '';
    if (top) desc += top[1];
    if (bot) desc += (desc ? '  ' : '') + bot[1];
    out.push({ title: ds.clean(tm[1]), pic: ds.pic(im ? im[1] : ''), desc: desc, url: ds.detailUrl(href) });
  }
  return out;
};

// ---- 简介折叠 ----
ds.setDesc = function (d, desc) {
  desc = ds.clean(desc);
  if (!desc) return;
  var short = desc.length > 90 ? desc.substr(0, 90) + '…' : desc;
  d.push({ title: '▎ 剧情简介\n' + short, col_type: 'text_1', url: 'hiker://empty', extra: { textSize: 14 } });
};

// ================= 单页视图架构 =================
// 所有列表（首页/分类/筛选/搜索/专题）都在「同一个页面」原地刷新：导航、筛选、搜索一律
// 写 myVar 状态后 refreshPage()，绝不返回 hiker://page/xxx 或 @rule 跳新页。
// 下滑自动翻页：顶层 rule 的 url 带 #page=fypage#，触底时引擎把 MY_PAGE 恰好 +1 并重跑本页
// 规则，新结果自动追加到列表末尾；用「水位 ds_wm」判定是不是真·自动翻页，避免重开规则误判。
ds.myPage = function () {
  try { var p = parseInt(MY_PAGE, 10); return (p > 0) ? p : 1; } catch (e) { return 1; }
};
// 生成「点一下原地切视图」的按钮链接。state 是 JSON 状态；回调在独立作用域，只吃形参 s。
ds.goRule = function (state) {
  return $('#noLoading#').lazyRule(function (s) {
    try {
      var o = JSON.parse(s);
      for (var k in o) if (o.hasOwnProperty(k)) putMyVar(k, String(o[k]));
    } catch (e) { }
    putMyVar('ds_nav', '1');   // 显式导航：强制第 1 页，忽略残留 MY_PAGE
    putMyVar('ds_pg', '1');
    refreshPage();
    return 'hiker://empty';
  }, typeof state === 'string' ? state : JSON.stringify(state));
};
// 单页架构下必须有回首页入口（否则切到搜索/筛选/专题后无法返回；顶部返回键会直接退出规则）
ds.homeBtn = function () {
  return { title: '🏠 首页', col_type: 'scroll_button', url: ds.goRule({ ds_view: 'home' }) };
};
// 视图分发：find_rule 调它；refreshPage 与下滑自动翻页都会重跑这里
ds.dispatch = function () {
  var v = getMyVar('ds_view', 'home');
  var paging = (v === 'catalog' || v === 'show' || v === 'search');
  var mp = ds.myPage();
  var wm = parseInt(getMyVar('ds_wm', '0'), 10) || 0;
  var nav = getMyVar('ds_nav', '0') === '1';
  if (nav) putMyVar('ds_nav', '0');
  var page = 1, headless = false;
  if (paging && !nav && wm > 0 && mp === wm + 1) {
    page = (parseInt(getMyVar('ds_pg', '1'), 10) || 1) + 1;   // 真·下滑自动翻页
    headless = true;
  }
  putMyVar('ds_wm', String(mp));
  if (paging) putMyVar('ds_pg', String(page));
  if (v === 'catalog') return ds.catalog(page, headless);
  if (v === 'show') return ds.show(page, headless);
  if (v === 'search') return ds.search(page, headless);
  if (v === 'topics') { if (headless) { setResult([]); return; } return ds.topics(); }
  if (headless) { setResult([]); return; }   // 首页/专题下滑不再追加，避免重复
  return ds.home();
};
// 专题卡片：首页与 /topic/home.html 都是 <a href="/topic/detail/{id}-.html" class="h-item">
ds.parseTopics = function (html) {
  var out = [];
  var re = /<a\s+href="([^"]+)"\s+class="h-item"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(html)) !== null) {
    var tm = /class="h-item-title">([^<]+)</.exec(m[2]);
    if (!tm) continue;
    var im = /(?:data-original|src)="([^"]*vod1[^"]*)"/.exec(m[2]);
    var bd = /h-item-top-right">\s*<span>([^<]+)<\/span>/.exec(m[2]);
    out.push({ title: ds.clean(tm[1]), pic: ds.pic(im ? im[1] : ''), badge: bd ? ds.clean(bd[1]) : '', url: ds.abs(m[1]) });
  }
  return out;
};

// ---- 首页 ----
ds.home = function () {
  var d = [];
  var base = ds.host();
  var html = '';
  var diag = [];
  try {
    // 只走 WebView / 安全通道，禁止裸 fetch 打 850
    html = ds.fetchHtml(base + '/');
    diag.push('len=' + String(html || '').length);
  } catch (e) {
    diag.push('err:' + String(e.message || e).slice(0, 40));
    log('ds home err ' + e);
  }

  if (!ds.guard(html)) {
    d.push({
      title: '⚠ 首页加载失败',
      desc: '诊断: ' + diag.join(' | ') + '\n站点有 cdndefend 反爬。请再点刷新；或点下方用网页打开。',
      col_type: 'text_1',
      url: 'hiker://empty'
    });
    d.push({
      title: '🔄 重新加载',
      col_type: 'text_center_1',
      url: $('#noLoading#').lazyRule(function () { refreshPage(true); return 'hiker://empty'; })
    });
    d.push({
      title: '🌐 网页模式打开站点',
      desc: base,
      col_type: 'text_center_1',
      url: base + '/'
    });
    d.push({
      title: '⚙ 设置域名',
      col_type: 'text_center_1',
      url: 'hiker://page/settings'
    });
    setResult(d);
    return;
  }
  try {
    // 1) 分类导航：全部「原地下钻到筛选视图」——同一页可下滑自动翻页 + 顶部筛选维度
    var chs = [['电影', '1'], ['连续剧', '2'], ['动漫', '3'], ['综艺', '4'], ['短剧', '6']];
    for (var i = 0; i < chs.length; i++) {
      d.push({
        title: chs[i][0],
        col_type: 'scroll_button',
        url: ds.goRule({ ds_view: 'show', ds_ch: chs[i][1], ds_f_g: '', ds_f_a: '', ds_f_l: '', ds_f_y: '', ds_f_s: '3', ds_f_p: '1' })
      });
    }
    d.push({
      title: '今日更新', col_type: 'scroll_button',
      url: ds.goRule({ ds_view: 'catalog', ds_cat: base + '/new/1.html', ds_cat_name: '今日更新' })
    });
    d.push({
      title: '专题', col_type: 'scroll_button',
      url: ds.goRule({ ds_view: 'topics' })
    });
    // 筛选入口（类型/地区/语言/年份/排序）
    d.push({
      title: '🎛 筛选', col_type: 'scroll_button',
      url: ds.goRule({ ds_view: 'show', ds_ch: '1', ds_f_p: '1' })
    });
    d.push({ col_type: 'line_blank' });

    // 2) 搜索框：确认后原地切到搜索视图（refreshPage），不另开页面
    d.push({
      title: '🔍 搜索影视',
      desc: '片名 / 演员 / 导演…',
      col_type: 'input',
      url: $.toString(function () {
        if (!input) return 'hiker://empty';
        putMyVar('keyword', input);
        putMyVar('ds_view', 'search');
        putMyVar('ds_nav', '1');
        putMyVar('ds_pg', '1');
        refreshPage();
      }),
      extra: {
        onChange: $.toString(function () { putMyVar('keyword', input); }),
        defaultValue: getMyVar('keyword', '')
      }
    });
    d.push({ col_type: 'line_blank' });

    // 3) 轮播 Banner
    var cars = [];
    var cre = /<a href="([^"]+)" class="carousel-item">([\s\S]*?)<\/a>/g, cm;
    while ((cm = cre.exec(html)) !== null) {
      var cb = cm[2];
      var ct = /carousel-item-title">([^<]+)</.exec(cb);
      if (!ct) continue;
      var cimg = /(?:data-original|src)="([^"]*vod1[^"]*)"/.exec(cb);
      var cdesc = /carousel-item-desc">([\s\S]*?)<\/div>/.exec(cb);
      cars.push({
        title: '🔥 ' + ds.clean(ct[1]),
        pic: ds.pic(cimg ? cimg[1] : ''),
        desc: ds.clean(cdesc ? cdesc[1] : '').slice(0, 42),
        url: ds.detailUrl(cm[1])
      });
    }
    if (cars.length) {
      var bid = 'ds_banner';
      var bi = parseInt(getMyVar('ds_bid', '0'), 10); if (isNaN(bi) || bi >= cars.length) bi = 0;
      var cur = cars[bi];
      d.push({ title: cur.title, desc: cur.desc, img: cur.pic, url: cur.url, col_type: 'pic_1_card', extra: { id: bid, gradient: true } });
      d.push({ col_type: 'line_blank' });
      try {
        unRegisterTask(bid);
        registerTask(bid, 4500, $.toString(function (o) {
          var items = o.items, id = o.id;
          var idx = parseInt(getMyVar('ds_bid', '0'), 10) + 1;
          if (isNaN(idx) || idx >= items.length) idx = 0;
          var it = items[idx];
          try { updateItem(id, { title: it.title, desc: it.desc, img: it.pic, url: it.url }); } catch (e) { unRegisterTask(id); }
          putMyVar('ds_bid', String(idx));
        }, { items: cars, id: bid }));
      } catch (e) { }
    }

    // 4) 分区（按 section-box 切分）
    var parts = html.split('<div class="section-box');
    var si2 = 0;
    for (var si = 1; si < parts.length; si++) {
      var seg = parts[si];
      var st = /section-header-title">([^<]+)</.exec(seg);
      if (!st) continue;
      var stitle = ds.clean(st[1]);
      if (stitle.indexOf('专题') >= 0) continue;
      var cards = ds.parseCards(seg);
      if (!cards.length) continue;
      var sc = ds.PALETTE[si2 % ds.PALETTE.length]; si2++;
      d.push({ title: '▎ ' + stitle, col_type: 'rich_text', url: 'hiker://empty', extra: { textSize: 17, lineVisible: false } });
      var max = (si === 1) ? 6 : 9;
      var colType = (si === 1) ? 'movie_2' : 'movie_3';
      for (var cc = 0; cc < cards.length && cc < max; cc++) {
        d.push({ title: cards[cc].title, desc: cards[cc].desc, pic_url: cards[cc].pic, url: cards[cc].url, col_type: colType });
      }
      d.push({ col_type: 'line_blank' });
    }

    // 5) 专题列表（首页自带；点卡片原地进入该专题的影片列表）
    var tops = ds.parseTopics(html);
    if (tops.length) {
      d.push({ title: '▎ 专题列表', col_type: 'rich_text', url: 'hiker://empty', extra: { textSize: 17, lineVisible: false } });
      for (var ti = 0; ti < tops.length && ti < 6; ti++) {
        d.push({
          title: tops[ti].title, desc: tops[ti].badge, pic_url: tops[ti].pic,
          url: ds.goRule({ ds_view: 'catalog', ds_cat: tops[ti].url, ds_cat_name: tops[ti].title }),
          col_type: 'movie_2'
