ds.search = function (page, headless) {
  try {
    var kw = getMyVar('keyword', '');
    if (!kw) { try { kw = String(MY_KEYWORD || ''); } catch (e) { } }
    if (kw && /%[0-9A-Fa-f]{2}/.test(kw)) { try { kw = decodeURIComponent(kw); } catch (e) { } }
    // 空关键词也要给出「输入框 + 回首页」入口，否则整页只剩一句提示、无路可退
    if (!kw) {
      setResult([ds.kwInput(), ds.homeBtn(), {
        title: '请输入搜索关键词', desc: '在上方输入片名 / 演员 / 导演后搜索',
        col_type: 'text_1', url: 'hiker://empty'
      }]);
      return;
    }
    var base = ds.host();
    page = parseInt(page, 10) || parseInt(getMyVar('ds_pg', '1'), 10) || 1;
    if (page < 1) page = 1;
    // 搜索必须带首页表单里的 t token（每次响应会轮换，缓存一份即可）
    var tok = getMyVar('ds_tok', '');
    if (page <= 1 || !tok) {
      var home = ds.fetchHtml(base + '/');
      var tm = /name="t"[^>]*value="([^"]+)"/.exec(home) || /value="([^"]+)"[^>]*name="t"/.exec(home);
      if (tm) { tok = tm[1]; putMyVar('ds_tok', tok); }
    }
    var surl = base + '/search?k=' + encodeURIComponent(kw) + '&t=' + encodeURIComponent(tok);
    if (page > 1) surl += '&page=' + page;
    var html = ds.fetchHtml(surl, base + '/');
    if (!ds.guard(html)) {
      setResult([ds.homeBtn(), ds.kwInput(), {
        title: '⚠ 搜索失败', desc: '反爬拦截或 token 失效，点此重试',
        col_type: 'text_1',
        url: $('#noLoading#').lazyRule(function () { putMyVar('ds_tok', ''); refreshPage(true); return 'hiker://empty'; })
      }]);
      return;
    }
    // 结果页会带出新的 t，缓存下来供下一页使用
    var nt = /\/search\?[^"']*[?&]t=([^"'&]+)/.exec(html);
    if (nt) { try { putMyVar('ds_tok', decodeURIComponent(nt[1])); } catch (e2) { } }
    var d = [];
    if (!headless) {
      d.push(ds.kwInput());
      d.push(ds.homeBtn());
      d.push({ title: '▎ 搜索：' + kw + (page > 1 ? '（第 ' + page + ' 页）' : ''), col_type: 'rich_text', url: 'hiker://empty', extra: { textSize: 17, lineVisible: false } });
      d.push({ col_type: 'line_blank' });
    }
    var nres = 0;
    var re = /<a href="(\/detail\/\d+\.html)" class="search-result-item">([\s\S]*?)<\/a>/g, m;
    while ((m = re.exec(html)) !== null) {
      var blk = m[2];
      var tm2 = /class="title">([^<]+)</.exec(blk);
      if (!tm2) continue;
      var im = /data-original="([^"]+)"/.exec(blk);
      var tags = /class="tags">([\s\S]*?)<\/div>/.exec(blk);
      var desc = /class="desc">([\s\S]*?)<\/div>/.exec(blk);
      var dd = ds.clean(tags ? tags[1] : '');
      if (desc) dd += (dd ? '\n' : '') + ds.clean(desc[1]).slice(0, 60);
      d.push({ title: ds.clean(tm2[1]), desc: dd, pic_url: ds.pic(im ? im[1] : ''), url: ds.detailUrl(m[1]), col_type: 'movie_3' });
      nres++;
    }
    if (!nres && !headless) d.push({ title: '未找到「' + kw + '」相关内容', desc: '换个关键词试试', col_type: 'text_1', url: 'hiker://empty' });
    setResult(d);
  } catch (e) { setError('搜索异常：' + e.message); setResult([]); }
};

