// ================= 筛选（/show/{频道}-{类型}-{地区}-{语言}-{年份}-{排序}-{页码}.html）=================
// 把筛选链接拆成视图状态对象（交给 ds.goRule 原地刷新）
ds.showHrefState = function (href) {
  var st = { ds_view: 'show', ds_f_p: '1' };
  var m = /\/show\/([^\/]+)\.html/.exec(ds.abs(href));
  if (!m) return st;
  var seg = m[1].split('-');
  var keys = ['ds_ch', 'ds_f_g', 'ds_f_a', 'ds_f_l', 'ds_f_y', 'ds_f_s'];
  for (var i = 0; i < keys.length; i++) {
    var v = seg[i] === undefined ? '' : seg[i];
    if (i === 0) v = v || '1';
    st[keys[i]] = v;
  }
  return st;
};

ds.show = function (page, headless) {
  try {
    var base = ds.host();
    var chs = [['1', '电影'], ['2', '连续剧'], ['3', '动漫'], ['4', '综艺'], ['6', '短剧']];
    var ch = getMyVar('ds_ch', '1') || '1';
    var g = getMyVar('ds_f_g', ''), a = getMyVar('ds_f_a', ''), lg = getMyVar('ds_f_l', ''), y = getMyVar('ds_f_y', '');
    var s = getMyVar('ds_f_s', '3') || '3';
    page = parseInt(page, 10) || parseInt(getMyVar('ds_f_p', '1'), 10) || 1;
    if (page < 1) page = 1;
    var chName = ch;
    for (var i = 0; i < chs.length; i++) if (chs[i][0] === ch) chName = chs[i][1];
    var path = '/show/' + ch + '-' + g + '-' + a + '-' + lg + '-' + y + '-' + s + '-' + page + '.html';
    var html = ds.fetchHtml(base + path, base + '/');
    var d = [];
    if (!ds.guard(html)) {
      d.push(ds.homeBtn());
      d.push({ title: '⚠ 筛选页加载失败', desc: path, col_type: 'text_1', url: 'hiker://empty' });
      d.push({ title: '🔄 重试', col_type: 'text_center_1', url: $('#noLoading#').lazyRule(function () { refreshPage(true); return 'hiker://empty'; }) });
      setResult(d); return;
    }
    if (!headless) {
      d.push(ds.homeBtn());
      // 频道选择（保留当前各筛选维度）
      for (var c = 0; c < chs.length; c++) {
        d.push({
          title: chs[c][1],
          col_type: 'scroll_button',
          url: ds.goRule({ ds_view: 'show', ds_ch: chs[c][0], ds_f_p: '1' }),
          extra: chs[c][0] === ch ? ds.ON : ds.OFF
        });
      }
      d.push({ col_type: 'line_blank' });
      // 各筛选维度：直接从页面解析（通用，站点改版也不用改代码）
      var rre = /filter-row-side">\s*<strong>([^<]+)<\/strong>\s*<\/div>\s*<div class="filter-row-main">([\s\S]*?)<\/div>/g, r2;
      while ((r2 = rre.exec(html)) !== null) {
        d.push({ title: '▎ ' + ds.clean(r2[1]), col_type: 'text_1', url: 'hiker://empty' });
        var ire = /<a href="([^"]+)"\s*class="filter-item([^"]*)">([^<]*)<\/a>/g, im2;
        while ((im2 = ire.exec(r2[2])) !== null) {
          var on = im2[2].indexOf('filter-item-active') >= 0;
          d.push({
            title: ds.clean(im2[3]),
            col_type: 'scroll_button',
            url: ds.goRule(ds.showHrefState(im2[1])),
            extra: on ? ds.ON : ds.OFF
          });
        }
        d.push({ col_type: 'line_blank' });
      }
      d.push({ title: '▎ ' + chName + ' · 筛选结果', col_type: 'rich_text', url: 'hiker://empty', extra: { textSize: 17, lineVisible: false } });
    }
    var cards = ds.parseCards(html);
    for (var q = 0; q < cards.length; q++) d.push({ title: cards[q].title, desc: cards[q].desc, pic_url: cards[q].pic, url: cards[q].url, col_type: 'movie_3' });
    if (!cards.length && !headless) d.push({ title: '暂无结果', col_type: 'text_1', url: 'hiker://empty' });
    setResult(d);
  } catch (e) { setError('筛选异常：' + e.message); setResult([]); }
};

// ---- 详情（海报 + 简介 + 线路 + 选集）----
ds.detail = function () {
  try {
    var url = ds.baseUrl();
    var html = ds.fetchHtml(url, ds.host() + '/');
    if (!ds.guard(html)) {
      setResult([{
        title: '⚠ 详情加载失败',
        desc: url + '\n请返回重试，或点下方用网页打开',
        col_type: 'text_1',
        url: 'hiker://empty'
      }, {
        title: '🌐 网页打开',
        col_type: 'text_center_1',
        url: url
      }]);
      return;
    }
    var d = [];

    var title = '';
    var h1 = /<h1[^>]*class="[^"]*detail[^"]*"[^>]*>([\s\S]*?)<\/h1>/.exec(html);
    if (h1) title = ds.clean(h1[1]);
    if (!title) { var pt = /<title>([^<]+)</.exec(html); if (pt) title = pt[1].split('-')[0].trim(); }
    var poster = '';
    var pm = /<img[^>]*(?:data-original|src)="([^"]*vod1\/vod\/(?:cover|upload)[^"]*)"/.exec(html);
    if (pm) poster = ds.pic(pm[1]);
    var score = /(豆瓣[:：]\s*[0-9.]+)/.exec(html);
    d.push({
      title: title, desc: score ? score[1] : '',
      pic_url: poster, url: poster ? (poster + '#.jpg#') : 'hiker://empty',
      col_type: 'movie_1_vertical_pic_blur', extra: { gradient: true }
    });

    var im = /<div class="detail-desc">\s*<p>([\s\S]*?)<\/p>/.exec(html);
    if (im) ds.setDesc(d, im[1]);
    d.push({ col_type: 'line' });

    // 线路名 + 各线路剧集（episode-list 顺序与 source-item 顺序一致）
    var names = [];
    var snre = /<span class="source-item-label">([^<]+)<\/span>/g, sm;
    while ((sm = snre.exec(html)) !== null) names.push(ds.clean(sm[1]));
    var groups = [];
    var gre = /<div class="episode-list"[^>]*>([\s\S]*?)<\/div>/g, gm;
    while ((gm = gre.exec(html)) !== null) {
      var eps = [];
      var ere = /<a href="([^"]+)"[^>]*class="episode-item"[^>]*>\s*<span>([^<]+)<\/span>/g, em;
      while ((em = ere.exec(gm[1])) !== null) eps.push({ name: ds.clean(em[2]), url: ds.epUrl(em[1]) });
      groups.push(eps);
    }
    if (!groups.length) { d.push({ title: '未找到播放资源', col_type: 'text_1', url: 'hiker://empty' }); setResult(d); return; }

    var vid = (/detail\/(\d+)/.exec(url) || [])[1] || 'x';
    var lk = 'ds_line_' + vid;
    var cur = parseInt(getMyVar(lk, '0'), 10); if (isNaN(cur) || cur < 0 || cur >= groups.length) cur = 0;
    if (names.length > 1) {
      for (var li = 0; li < names.length; li++) {
        var active = (li === cur);
        d.push({
          title: names[li],
          col_type: 'scroll_button',
          url: $('#noLoading#').lazyRule(function (i, k) { putMyVar(k, String(i)); refreshPage(false); return 'hiker://empty'; }, li, lk),
          extra: active ? { backgroundColor: '#FF6B81', textColor: '#FFFFFF', textSize: 14 } : { textSize: 14 }
        });
      }
      d.push({ col_type: 'line_blank' });
    }
    var eps = groups[cur] || [];
    var ct = eps.length > 50 ? 'text_5' : eps.length > 20 ? 'text_4' : eps.length > 8 ? 'text_3' : 'text_2';
    for (var j = 0; j < eps.length; j++) d.push({ title: eps[j].name, url: eps[j].url, col_type: ct });
    setResult(d);
  } catch (e) { setError('详情异常：' + e.message); setResult([]); }
};

// ---- 播放 ----
ds.play = function () {
  try {
    var url = ds.baseUrl();
    var html = ds.fetchHtml(url, ds.host() + '/');
    if (!html || html.length < 800) return 'toast://播放页加载失败';
    var m = /src:\s*"([^"]+\.m3u8[^"]*)"/.exec(html) || /(https?:\/\/[^"'\s]+\.m3u8[^"'\s]*)/.exec(html);
    if (m) return m[1] + '#isVideo=true#';
    if (html.indexOf('仅供APP') >= 0) return 'toast://该线路仅供APP端观看，请切换其它线路';
    return 'video://' + url;
  } catch (e) { return 'toast://解析失败：' + e.message; }
};

